 if(tabIs('Servisní plán'))body=notice(`${v.plan==='Ke schválení'?'Úkol: potvrdit servisní plán před použitím pro hlídání servisu.':'Plán je potvrzený; A2 používá poslední ověřený nájezd.'} Zdroj: ukázkový katalog výrobce, verze 2026.2. ${v.plan==='Ke schválení'?'Nově získaná data ze STK plán sama nepotvrzují.':''}`,'warning')+table(['Úkon','Interval km / čas','Poslední provedení','Další hranice','Stav'],[['Motorový olej a filtry',v.id==='v2'?'30 000 km / 12 měsíců':'60 000 km / 12 měsíců',v.id==='v2'?'57 000 km · 28. 10. 2025':'240 000 km · 12. 01. 2026',v.id==='v2'?'87 000 km · 28. 10. 2026':'300 000 km · 12. 01. 2027',badge(v.plan)],['Brzdová soustava','30 000 km / 6 měsíců','270 000 km · 05. 08. 2026','300 000 km · 05. 02. 2027',badge(v.plan)],['Pneumatiky / geometrie','20 000 km / 6 měsíců','280 000 km · 01. 09. 2026','300 000 km · 01. 03. 2027',badge(v.plan)]])+`<div class="actions section-space">${btn('Upravit plán','form:plan','edit')}${btn('Potvrdit plán','simulate:Potvrzení servisního plánu','check','primary')}${btn('Zdroj a rozdíly verze','catalog-diff','file')}</div>`;
