function orders(){return head('Zakázky','Od přijetí objednávky po doručení a uzavření přepravy.',btn('Nová zakázka','new-order','plus','primary'))+`<div class="panel">${toolbar('Hledat zakázku, zákazníka nebo trasu…',[['state','Všechny stavy',['Přijatá','K doplnění','K přiřazení','Přiřazená','Probíhá','Dokončená','Uzavřená','Zrušená','Konflikt přiřazení']],['type','Typ vozidla',['Kamion','Nákladní vozidlo','Dodávka']]])}<div id="list-results">${orderTable(DEMO.orders)}</div><div class="panel-foot">6 demo zakázek · včetně neúplné objednávky a konfliktu po odstavení vozu</div></div>`;}
