function filters(){const search=($('[data-filter="search"]')?.value||'').toLocaleLowerCase('cs');const filterValues={};document.querySelectorAll('select[data-filter]').forEach(s=>filterValues[s.dataset.filter]=s.value);const matches=(item)=>{const text=JSON.stringify(item)+' '+(getV(item.vehicle)?.spz||'')+' '+(getD(item.driver)?.name||'');if(!text.toLocaleLowerCase('cs').includes(search))return false;return Object.entries(filterValues).every(([key,val])=>!val||(key==='vehicle'?getV(item.vehicle)?.spz===val:key==='reserve'?(item.reserve?'Ano':'Ne')===val:item[key]===val));};
 let list,html;if(currentPage==='vehicles'){list=DEMO.vehicles.filter(matches);html=vehicleTable(list);}else if(currentPage==='drivers'){list=DEMO.drivers.filter(matches);html=driverTable(list);}else if(currentPage==='orders'){list=DEMO.orders.filter(matches);html=orderTable(list);}else if(currentPage==='trips'){list=DEMO.trips.filter(matches);html=tripTable(list);}else if(currentPage==='documents'){list=DEMO.docs.filter(matches);html=documentTable(list);}else if(currentPage==='costs'){list=DEMO.fuel.filter(matches);html=fuelTable(list);}if($('#list-results'))$('#list-results').innerHTML=emptyMode&&['vehicles','documents'].includes(currentPage)?empty(currentPage==='vehicles'?'vozidla':'dokumenty'):html||'';if($('.toolbar .results'))$('.toolbar .results').textContent=`${list?.length||0} záznamů · ukázková data`;}
function reportFilter(){const period=$('#report-period').value,v=$('#report-vehicle').value,cat=$('#report-category').value,cost=$('#report-costs').value;let list=reportData().filter(r=>(!v||r[0]===v)&&(!cat||r[1]===cat));if(period!=='2026-10')list=[];if(cost==='Pouze palivo')list=list.map(r=>{const f=({'4AB 2186':'12 460,50 Kč','5AX 9042':'2 483,60 Kč','8AZ 6721':'1 489,80 Kč'})[r[0]]||'Nedoloženo';return [...r.slice(0,6),r[5],r[7],f,r[9]];});if(cost==='Bez paliva')list=list.map(r=>[...r.slice(0,5),'Nezahrnuto',r[0]==='4AB 2186'?'13,15 Kč/km':r[0]==='5AX 9042'?'−0,61 Kč/km':'0 Kč/km',r[7],r[0]==='4AB 2186'?'21 600 Kč':r[0]==='5AX 9042'?'−250 Kč':'0 Kč',r[9]]);$('#report-table').innerHTML=reportRows(list);$('#report-filter-note').innerHTML=notice(period==='2026-10'?`Filtrovaná tabulka: ${esc(v||cat||'všechna vozidla')} · ${esc(cost)}. Grafy a horní karty ukazují celkový říjnový demo souhrn.`:'Pro zvolené období nejsou demo podklady. Grafy a horní karty jsou označený říjnový vzor.','blue');}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();handleAction(target.dataset.action);}const tab=e.target.closest('[data-tab]');if(tab){go(currentPage,currentId||'',tab.dataset.tab);}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){role=e.target.value;emptyMode=false;if(role==='Řidič')go('driver-home');else if(currentPage==='driver-home'||currentPage.startsWith('my-'))go('overview');else render();}if(e.target.matches('[data-filter]'))filters();if(e.target.matches('[data-empty]')){emptyMode=e.target.checked;render();}if(e.target.id==='upload-files')$('#selected-files').textContent=Array.from(e.target.files).map(f=>f.name).join(' · ')||'PDF, JPG, PNG · více stran';if(e.target.id.startsWith('report-'))reportFilter();});
document.addEventListener('input',e=>{if(e.target.matches('[data-filter="search"]'))filters();});
document.addEventListener('submit',e=>{if(e.target.matches('[data-demo-form]')){e.preventDefault();const type=e.target.dataset.type|| (currentPage==='my-fault'?'fault':'fuel');const entries=Array.from(new FormData(e.target).entries()).filter(([k,v])=>typeof v==='string'&&v);const preview=entries.slice(0,12).map(([k,v])=>[esc(k.replace(/_/g,' ')),esc(v)]);openModal('Náhled · '+(formTitles[type]||'záznam'),notice('Návrh nebyl uložen ani odeslán. Následující údaje ilustrují budoucí obsah záznamu.','blue')+dataGrid(preview)+(type==='fault'?`<div class="section-space">${notice('A1 · Po odeslání by následoval návrh priority a posouzení manažerem. Pravidlo A9: Nutno nastavit.')}</div>`:type==='trip-end'?`<div class="section-space">${notice('Bez koncového tachometru by záznam zůstal ukončený neúplný. A6 až po 72 h při nejbližší denní kontrole.','warning')}</div>`:''),btn('Zavřít náhled','close-modal')+btn('Upravit návrh',`form:${type}`,'edit','primary'));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal')){closeModal();return;}if(e.key==='Tab'&&$('.modal')){const focusables=Array.from($('.modal').querySelectorAll('button,input,select,textarea,a[href]')).filter(el=>!el.disabled);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();const q=e.target.value.toLocaleLowerCase('cs');const hits=[...DEMO.vehicles.map(v=>({text:v.spz+' '+v.model,route:'vehicle/'+v.id})),...DEMO.drivers.map(d=>({text:d.name,route:'driver/'+d.id})),...DEMO.orders.map(o=>({text:o.number+' '+o.customer,route:'order/'+o.id}))].filter(x=>x.text.toLocaleLowerCase('cs').includes(q));openModal('Výsledky hledání',q?hits.length?`<div class="stack">${hits.map(h=>btn(esc(h.text),'navigate:'+h.route,'arrow')).join('')}</div>`:empty('výsledky'):notice('Zadejte SPZ, jméno řidiče nebo číslo zakázky.'),btn('Zavřít','close-modal'));}});
window.addEventListener('hashchange',()=>{if($('.modal'))closeModal();render();});
